const update = $input.first().json;

const SERVICES = {
  haircut: { name: '✂️ Мужская стрижка', price: 1800, duration: '45 мин' },
  manicure: { name: '💅 Маникюр с покрытием', price: 2200, duration: '60 мин' },
  autocheck: { name: '🚗 Экспресс-ТО', price: 1500, duration: '30 мин' }
};
const SLOTS = ['11:00', '14:00', '16:30', '19:00'];

function demoDates() {
  const now = new Date();
  const wd = ['Вс','Пн','Вт','Ср','Чт','Пт','Сб'];
  const mo = ['янв','фев','мар','апр','мая','июн','июл','авг','сен','окт','ноя','дек'];
  return [0,1,2].map(i => {
    const d = new Date(now); d.setDate(now.getDate()+i);
    const pre = i===0?'Сегодня':i===1?'Завтра':wd[d.getDay()];
    return { label:`${pre} (${d.getDate()} ${mo[d.getMonth()]})`, iso:d.toISOString().split('T')[0], display:`${pre}, ${d.getDate()} ${mo[d.getMonth()]}` };
  });
}

let chatId, from, cbd=null;
if (update.callback_query) {
  chatId = update.callback_query.message.chat.id;
  from = update.callback_query.from;
  cbd = update.callback_query.data;
} else if (update.message) {
  chatId = update.message.chat.id;
  from = update.message.from;
}
const name = from?.first_name||'Гость';
const uname = from?.username ? '@'+from.username : '';

let text='', kb=[], confirmed=false, booking=null;

if (cbd) {
  const p = cbd.split('|');
  if (p[0]==='srv') {
    const s = SERVICES[p[1]];
    text = `Вы выбрали: <b>${s.name}</b> (${s.price} ₽)\n\n📅 <b>Выберите день:</b>`;
    kb = demoDates().map(d => [{ text:d.label, callback_data:'dt|'+p[1]+'|'+d.iso }]);
    kb.push([{ text:'« Назад', callback_data:'start' }]);
  } else if (p[0]==='dt') {
    const s = SERVICES[p[1]];
    const dd = demoDates().find(d=>d.iso===p[2]);
    text = `${s.name}\n📅 ${dd?dd.display:p[2]}\n\n⏰ <b>Выберите время:</b>`;
    kb = [];
    for (let i=0;i<SLOTS.length;i+=2) {
      const row = [{ text:'🕐 '+SLOTS[i], callback_data:'tm|'+p[1]+'|'+p[2]+'|'+SLOTS[i] }];
      if (SLOTS[i+1]) row.push({ text:'🕐 '+SLOTS[i+1], callback_data:'tm|'+p[1]+'|'+p[2]+'|'+SLOTS[i+1] });
      kb.push(row);
    }
    kb.push([{ text:'« Назад', callback_data:'srv|'+p[1] }]);
  } else if (p[0]==='tm') {
    const s = SERVICES[p[1]];
    const dd = demoDates().find(d=>d.iso===p[2]);
    const bid = 'RB-'+Math.floor(1000+Math.random()*9000);
    confirmed = true;
    booking = {
      booking_id:bid, created_at:new Date().toISOString(),
      client_id:String(from?.id||''), client_name:name,
      telegram_username:uname, service_name:s.name,
      price:s.price, date_display:dd?dd.display:p[2],
      time_slot:p[3], status:'Подтверждена'
    };
    text = '🎉 <b>Запись подтверждена!</b>\n\n'+
      '📋 #'+bid+'\n'+
      '✂️ '+s.name+'\n'+
      '💰 '+s.price+' ₽ ('+s.duration+')\n'+
      '📅 '+(dd?dd.display:p[2])+'\n'+
      '⏰ '+p[3]+'\n'+
      '👤 '+name+' ('+uname+')';
    kb = [[{ text:'🔄 Записаться снова', callback_data:'start' }]];
  } else { cbd='start'; }
}

if (!cbd||cbd==='start') {
  text = '👋 <b>Здравствуйте, '+name+'!</b>\n\nЭто демо-стенд <b>ReBook</b>.\nЗапишитесь за 30 секунд:\n\n👇 <b>Выберите услугу:</b>';
  kb = Object.entries(SERVICES).map(([k,v]) => [{ text:v.name+' — '+v.price+' ₽', callback_data:'srv|'+k }]);
}

return [{ json: { chatId, text, reply_markup:{ inline_keyboard:kb }, confirmed, booking } }];
